"""Derive component fields and cross-tier links from the schemas and dependency graph."""
import json
from collections import defaultdict
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
def r(f):return json.loads((ROOT/f).read_text())
reg=r('schemas/component-registry.json')['kinds'];cats=r('schemas/catalog-item.schema.json')['$defs'];sels=r('schemas/selection.schema.json')['$defs'];edges=r('baseline/core-dependency-graph.json')['edges']
links=defaultdict(list)
for e in edges:
 if reg[e['dependent_kind']]['tier']!=reg[e['depends_on_kind']]['tier']:
  links[e['dependent_kind']].append(f"{e['depends_on_kind']} [{reg[e['depends_on_kind']]['tier']}]")
out=['# Component catalog and selection schema','', 'The **29** canonical component `kind` values. All component IDs are stable; an item of a given kind can be used in more than one build or role. Types, requiredness, and allowed enum values are defined in JSON Schema, not this descriptive table.','', '| Tier | Kind (`kind`) | Required catalog spec keys | Required selection settings | Cross-tier dependencies (examples) |','|---|---|---|---|---|']
for kind,desc in reg.items():
 spec=cats['spec_'+kind]
 select=sels['settings_'+kind]
 s=', '.join('`'+k+'`' for k in spec['required']) or '—'
 s2=', '.join('`'+k+'`' for k in select['required']) or '—'
 lk=', '.join(dict.fromkeys(links.get(kind,[]))) or '—'
 out.append(f"| {desc['tier']} | `{kind}` | {s} | {s2} | {lk} |")
out+=['','## Universal catalog item envelope','', 'All catalog items must contain: `schema_version`, `id`, `kind`, `tier`, `name`, `version`, `status`, `billing_class`, `spec`, `provenance`, and `updated_at`. Optional fields include `description`, `tags`, verified `license`, and namespaced `extensions`. Catalog `spec` has 29 strict discriminated variants (one per kind); vendor-specific experimental data belongs in `extensions`.','', '## Universal selection envelope','', 'All selections must contain: `id`, `kind`, `catalog_item_id`, `catalog_item_version`, `role`, `enabled`, and typed `settings`. A component selected twice for different purposes must have distinct `id` and `role` values. The `role` is only meaningful **within a component kind** (e.g., generative model `primary`, `fallback`; multiple embedding indexes might use `documents` and `memory`).','', '## Essential units and scoping','', '- Tokens are **tokens**, never kilotokens unless a property explicitly includes `_1m`. Context request is prompt budget and reserved output; compare their sum to model maximum.','- `vram_gb` is device VRAM in GB; `device_count` is physical/logical selected devices. Do not assume multi-GPU VRAM can be pooled without engine/model parallelism support.','- `region` uses a canonical deployment-provider region identifier or a validated user-residency mapping; do not compare incompatible provider geographies by free text.','- `embedding_dimensions` describes supported model dimensions, while `vector_database.settings.index_dimension` describes a **particular index**. Changing dimensions typically requires an index rebuild.','- Model inference `precision`, quantization and context choices are specific to each selected model and engine; model/accelerator/backend constraints are joint and not just pairwise.','- API-only builds can omit a local GPU/inference runtime. Keyword-only RAG need not select embeddings or a vector database.','- `credential_ref` values start `secret://` and are opaque references, not credentials.','- Price amounts and quantities are decimal strings; units are explicit; timestamps are RFC 3339 and catalog evidence is dated.','','## Enforced structural relationship examples','','- `model.spec.provider_ref` resolves to a `model_provider` catalog item; an active model selection is linked to its provider.','- `compute_profile.spec.accelerator_ref` resolves to a selected `accelerator`, and `hosting_ref` to the selected platform.','- `training_compute.spec.compute_profile_ref` must reference a compute SKU already known in the catalog.','- `knowledge_base.spec.data_source_refs` and `training_dataset.spec.data_source_refs` refer to `data_source` catalog items; they are not inline contents.','- `fine_tuned_model.spec.base_model_ref`, `.training_framework_ref`, and `.training_dataset_ref` form immutable lineage.','- `memory_store` may reuse `vector_database` or `storage`, and does not create another independent vector DB.','','See `docs/DEPENDENCIES.md` for conditional rule semantics, non-tree relationships and invalidation.','']
(ROOT/'docs/COMPONENTS.md').write_text('\n'.join(out),encoding='utf-8')
print('Generated docs/COMPONENTS.md:',len(reg),'kinds')
